var canFinish = function(numCourses, prerequisites) {
    const graph = Array.from({ length: numCourses }, () => []);
    const indegree = new Array(numCourses).fill(0);

    for (const [course, prerequisite] of prerequisites) {
        graph[prerequisite].push(course);
        indegree[course] += 1;
    }

    const ready = [];
    for (let course = 0; course < numCourses; course++) {
        if (indegree[course] === 0) ready.push(course);
    }

    let completed = 0;
    let head = 0;
    while (head < ready.length) {
        const prerequisite = ready[head++];
        completed += 1;
        for (const course of graph[prerequisite]) {
            indegree[course] -= 1;
            if (indegree[course] === 0) ready.push(course);
        }
    }

    return completed === numCourses;
};

solution.python:
from collections import deque
from typing import List


class Solution:
    def canFinish(
        self, numCourses: int, prerequisites: List[List[int]]
    ) -> bool:
        graph = [[] for _ in range(numCourses)]
        indegree = [0] * numCourses

        for course, prerequisite in prerequisites:
            graph[prerequisite].append(course)
            indegree[course] += 1

        ready = deque(
            course for course in range(numCourses) if indegree[course] == 0
        )
        completed = 0

        while ready:
            prerequisite = ready.popleft()
            completed += 1
            for course in graph[prerequisite]:
                indegree[course] -= 1
                if indegree[course] == 0:
                    ready.append(course)

        return completed == numCourses
